require __DIR__.'/boot.php';
$sessionDir=CHOPPRO_STORAGE_ROOT.'/owner-sessions';if(!is_dir($sessionDir))mkdir($sessionDir,0700,true);session_save_path($sessionDir);session_name('choppro_owner');session_set_cookie_params(['path'=>(CHOPPRO_HOST_BASE?:'').'/','httponly'=>true,'secure'=>!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off','samesite'=>'Strict']);ini_set('session.use_strict_mode','1');session_start();$_SESSION['csrf']??=bin2hex(random_bytes(32));
$site=require $loader->private.'/site.php';$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    try{
