        $action=$_POST['action']??'';
        if($action==='login'){
            $key=hash('sha256',$_SERVER['REMOTE_ADDR']??'local');$file=$loader->private.'/owner-attempts.json';$lock=fopen($loader->private.'/owner.lock','c');flock($lock,LOCK_EX);$rates=$loader->json($file);$rate=$rates[$key]??['attempts'=>0,'until'=>time()+600];if($rate['until']<time())$rate=['attempts'=>0,'until'=>time()+600];$rate['attempts']++;$rates[$key]=$rate;$loader->atomic($file,json_encode($rates));flock($lock,LOCK_UN);fclose($lock);if($rate['attempts']>10)throw new RuntimeException('Слишком много попыток входа. Повторите через 10 минут');
            if(!password_verify($_POST['password']??'',$site['owner_password_hash']??''))throw new RuntimeException('Неверный пароль владельца');session_regenerate_id(true);$_SESSION['owner_until']=time()+3600;$_SESSION['csrf']=bin2hex(random_bytes(32));$message='Вход выполнен';
