            }elseif($action==='worker'){$release=host_release('demo');require $release['path'].'/backend/src/Core/Autoloader.php';$config=\Choppro\Stage2\Config::load();$result=(new \Choppro\Stage2\Worker(new \Choppro\Stage2\Db($config),$config))->tick();$message='Обработка документов, напоминаний и неявок выполнена';}
